using System;using System.IO;using System.Linq;using System.Reflection;using Newtonsoft.Json;using Rubezh.Camp;using Rubezh.UnityPort;using SilentOrders.Core;using SilentOrders.Rendering;using UnityEngine;using UnityEngine.UIElements;
class RareWeaponsCheck {
 static int count;static void Check(bool ok,string why){if(!ok)throw new Exception(why);count++;}
 static void Near(float a,float b,string why){Check(Math.Abs(a-b)<.0001f,why+" "+a+"/"+b);}
 static Soldier Gun(int variant,bool west=false,Side side=Side.Green,Role role=Role.Rifleman)=>new Soldier{WeaponVariant=variant,WesternGun=west,Side=side,Role=role,GunRoleOverride=variant>=4?(int)Role.Sniper:variant==1?(int)Role.MachineGunner:(int)Role.Rifleman};
 static void Main(){
 var ak=Gun(0);var m4=Gun(0,true);var mg=Gun(1);var m249=Gun(1,true);var svd=Gun(4,false,Side.Green,Role.Sniper);var m24=Gun(5,true,Side.Green,Role.Sniper);
 Near(WeaponBalance.For(ak).FireSeconds/WeaponBalance.For(m4).FireSeconds,1.15f,"M4 rate");Near(WeaponBalance.For(m4).Accuracy,1.1f,"M4 accuracy");Near(WeaponBalance.For(m4).Spread,.9f,"M4 scatter");
 Near(WeaponBalance.For(Gun(3,true)).Accuracy,WeaponBalance.For(Gun(2)).Accuracy*1.1f,"GP accuracy");Near(WeaponBalance.For(Gun(3,true)).FireSeconds,WeaponBalance.For(m4).FireSeconds,"GP interval");
 Near(WeaponBalance.For(m249).Range,19.9f,"M249 range unchanged");Near(WeaponBalance.For(m249).Accuracy,1.1f,"M249 accuracy");Near(WeaponBalance.For(m249).Spread,.9f,"M249 scatter");
 foreach(float roll in new[]{18f,24f,30f}){Near(WeaponBalance.BulletDamage(m249,roll),WeaponBalance.BulletDamage(mg,roll)-2,"M249 damage -2");Near(WeaponBalance.BulletDamage(m24,roll),WeaponBalance.BulletDamage(svd,roll)+5,"M24 damage +5");}
 Near(WeaponBalance.CriticalChance(m24,false),.3f,"M24 critical 30%");Near(WeaponBalance.CriticalChance(Gun(5,true),false),.2f,"rifleman M24 critical 20%");Near(WeaponBalance.For(m24).Accuracy,10.89f,"M24 accuracy");Check(m24.MagazineSize==5,"M24 magazine");Near(WeaponBalance.For(m24).FireSeconds,5.4f,"M24 interval");
 foreach(int variant in new[]{0,1,3,5}){var green=Gun(variant,true);var red=Gun(variant,false,Side.Red);Check(WeaponBalance.Index(green)==WeaponBalance.Index(red),"same weapon both sides");}
 var recovered=Gun(0,true);recovered.ActiveRecoveredWeapon=true;Near(WeaponBalance.For(recovered).Accuracy,1,"picked AK does not inherit M4");recovered.WeaponVariant=7;Check(recovered.WeaponModel==1&&WeaponBalance.Index(recovered)==7,"absolute picked M249");Check(BattleRenderer.WesternWeapon(recovered,9),"picked western rendering");
 var a=new BattleSimulation(125);var b=new BattleSimulation(125);for(int n=0;n<40;n++){bool x,y;var p=new V2(8.5f,8.5f);var aa=Ballistics.AimPoint(a,new V2(2,2),p,1,out x);var bb=Ballistics.AimPoint(b,new V2(2,2),p,1,out y,.9f);Near(V2.Distance(bb,p),V2.Distance(aa,p)*.9f,"scatter scale");}

 svd.Health=m24.Health=40;svd.AccuracyFactor=m24.AccuracyFactor=1;svd.Morale=m24.Morale=1;svd.Position=m24.Position=new V2(3,3);float qa=Ballistics.Accuracy(a,svd,new V2(5,5),false,false);float qb=Ballistics.Accuracy(a,m24,new V2(5,5),false,false);Near(qb,Math.Min(.98f,qa*1.1f),"M24 accuracy bonus survives penalties");
 var catalog=JsonConvert.DeserializeObject<Catalog>(File.ReadAllText("Assets/Rubezh/Resources/FieldCamp/catalog.json"),CampModel.JsonSettings);var model=new CampModel(catalog,rng:()=>.37);model.S.balance=10000;
 string[] ids={"m4gp","m249","m24","m4"};foreach(var id in ids){var item=catalog.Item(id);Check(item!=null&&item.rarity=="Редкое"&&model.Unlocked(item),"rare at story zero "+id);model.Buy(id);}
 var members=model.S.active.ToArray();for(int i=0;i<4;i++)model.Equip(members[i],"weapon",ids[i]);var saved=new CampModel(catalog,CampModel.Decode(model.Serialize()));for(int i=0;i<4;i++)Check(saved.S.gear[members[i]].weapon==ids[i],"saved weapon");
 Resources.Loader=p=>{var path="Assets/Rubezh/Resources/"+p;if(File.Exists(path+".json"))return new TextAsset{text=File.ReadAllText(path+".json")};if(File.Exists(path+".bytes"))return new TextAsset{bytes=File.ReadAllBytes(path+".bytes")};if(File.Exists(path+".png"))return new Texture2D(1,1,TextureFormat.RGBA32,false);if(p.Contains("Fonts/"))return new Font();if(p=="FieldCamp/Camp")return new StyleSheet();if(p=="FieldCamp/CampTheme")return new ThemeStyleSheet();return null;};
 var dir=Path.Combine(Path.GetTempPath(),"rubezh125-"+Guid.NewGuid());Directory.CreateDirectory(dir);var store=new CampStore(Path.Combine(dir,"save.json"),saved);var view=new NativeCampView();Screen.width=1280;Screen.height=720;Screen.safeArea=new Rect(0,0,1280,720);view.Initialize(store,false);var order=view.CreateOrder();order.mode="war";order.block=1;order.mission=1;var sim=RubezhApp.BuildCampSimulation(order);
 int[] profiles={9,7,11,6};for(int i=0;i<4;i++){Check(WeaponBalance.Index(sim.Soldiers[i])==profiles[i],"loadout reaches battle");Check(BattleRenderer.WesternWeapon(sim.Soldiers[i],i==1?9:8),"western gun rendered");}
 Check(sim.Soldiers[0].Underbarrel,"M4 GP works");
 Near(GrenadePockets.Count(sim.Soldiers[0],2),sim.Soldiers[0].LoadedUnderbarrel,"GP loaded round counted");Check(sim.Soldiers[1].GunMachineGunner,"M249 machinegun rules");Check(sim.Soldiers[2].GunSniper&&sim.Soldiers[2].Ammo==5,"M24 sniper ammo");
 Rubezh.Graphics.ConfigurePacks();var pages=Rubezh.Graphics.PagesFor(sim.Map);Rubezh.Graphics.AddLookPages(pages,sim);var looks=Rubezh.Graphics.LookSprites(sim);foreach(int page in pages)Rubezh.Graphics.LoadPage(page,File.ReadAllBytes("Assets/Rubezh/Editor/LegacySources/"+Rubezh.SpritePackIndex.Path(page)+".bytes"),looks:looks);Rubezh.Graphics.BakeLooks(sim);new BattleRenderer(BattleRenderer.HighScale).Render(sim);for(int step=0;step<120;step++)sim.Step();new BattleRenderer(BattleRenderer.HighScale).Render(sim);Check(true,"rare weapons render and simulate");
 Rubezh.Graphics.ReleaseSceneSprites();Directory.Delete(dir,true);Console.WriteLine("PASS rare weapons checks="+count+"; contract runtime, no Unity device execution");
 }
}
